begin;
set local request.jwt.claims='{"aal":"aal2"}';
select plan(27);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000601','reports-staff@example.test'),('00000000-0000-4000-8000-000000000609','reports-brand@example.test');
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000601';
insert into public.brands(id,name,can_see_customer_names) values('00000000-0000-4000-8000-000000000602','Report A',false),('00000000-0000-4000-8000-000000000603','Report B',true);
insert into public.brand_users(brand_id,user_id) values('00000000-0000-4000-8000-000000000602','00000000-0000-4000-8000-000000000609');
insert into public.customers(id,legal_name,city) values('00000000-0000-4000-8000-000000000604','Private Report Customer','Roma');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000605','00000000-0000-4000-8000-000000000602','REPORT','Report A'),('00000000-0000-4000-8000-000000000606','00000000-0000-4000-8000-000000000603','REPORT','Report B');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents) values('00000000-0000-4000-8000-000000000607','00000000-0000-4000-8000-000000000602','00000000-0000-4000-8000-000000000605','REPORT-TEST','Report product',1000);
insert into public.product_variants(id,product_id,brand_id,size,color,sku) values('00000000-0000-4000-8000-000000000608','00000000-0000-4000-8000-000000000607','00000000-0000-4000-8000-000000000602','M','Nero','REPORT-TEST-M');
insert into public.customer_contacts(id,customer_id,name,email) values('00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000604','Buyer','buyer@example.test');
create temporary table report_orders(id uuid,seq int);grant all on report_orders to authenticated;
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000601';
do $$declare v_id uuid;v_i int;begin
for v_i in 1..4 loop
v_id:=public.save_order(null,jsonb_build_object('brand_id','00000000-0000-4000-8000-000000000602','customer_id','00000000-0000-4000-8000-000000000604','season_id','00000000-0000-4000-8000-000000000605','order_date',case when v_i=2 then '2032-02-01' else '2032-01-01' end,'delivery_date','','discount_pct',0,'internal_notes','Report secret notes'),jsonb_build_array(jsonb_build_object('variant_id','00000000-0000-4000-8000-000000000608','quantity',v_i,'unit_price_cents',1000,'discount_pct',0)));
insert into report_orders values(v_id,v_i);
if v_i in (1,2) then perform public.change_order_status(v_id,'confirmed','');end if;
if v_i=4 then perform public.change_order_status(v_id,'cancelled','');end if;
end loop;end;$$;


create temporary table confirmation_claim(data jsonb); grant all on confirmation_claim to authenticated;
insert into confirmation_claim select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610');
select is((select data->>'state' from confirmation_claim),'pending','claim created');
select is((select data->>'recipient' from confirmation_claim),'buyer@example.test','contact recipient resolved server side');
select is((select data->'payload'->>'net_cents' from confirmation_claim),'1000','commercial snapshot uses exact cents');
select ok((select data::text not like '%Report secret notes%' and not (data->'payload' ? 'commission_pct_override') from confirmation_claim),'private order data omitted');
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610')$$,'55P03',null,'concurrent claim refused');
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=3),'00000000-0000-4000-8000-000000000610')$$,'23514',null,'draft cannot send');
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=4),'00000000-0000-4000-8000-000000000610')$$,'23514',null,'cancelled cannot send');
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000608')$$,'23514',null,'unrelated recipient refused');
select throws_ok($$select public.finish_order_confirmation((select (data->>'id')::uuid from confirmation_claim),gen_random_uuid(),'logged')$$,'40001',null,'incorrect lease cannot complete');
select throws_ok($$select public.finish_order_confirmation((select (data->>'id')::uuid from confirmation_claim),(select (data->>'lease')::uuid from confirmation_claim),'unknown')$$,'23514',null,'completion state validated');
select lives_ok($$select public.finish_order_confirmation((select (data->>'id')::uuid from confirmation_claim),(select (data->>'lease')::uuid from confirmation_claim),'logged')$$,'local completion recorded');
select is(public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610')->>'duplicate','true','completed delivery cannot be sent twice');
select is(public.order_confirmation_history((select id from report_orders where seq=1))->0->>'state','logged','durable history distinguishes log from real delivery');
select ok(not (public.order_confirmation_history((select id from report_orders where seq=1))->0 ? 'recipient'),'history does not include email body or address');
insert into confirmation_claim select public.prepare_order_confirmation((select id from report_orders where seq=2),'00000000-0000-4000-8000-000000000610');
select lives_ok($$select public.finish_order_confirmation((select (data->>'id')::uuid from confirmation_claim where data->'payload'->>'net_cents'='2000'),(select (data->>'lease')::uuid from confirmation_claim where data->'payload'->>'net_cents'='2000'),'failed')$$,'failed lease released');
select is(public.prepare_order_confirmation((select id from report_orders where seq=2),'00000000-0000-4000-8000-000000000610')->>'id',(select data->>'id' from confirmation_claim where data->'payload'->>'net_cents'='2000'),'retry retains provider idempotency key');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000609';
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610')$$,'42501',null,'brand cannot send');
select throws_ok($$select public.order_confirmation_history((select id from report_orders where seq=1))$$,'42501',null,'brand cannot read delivery history');
reset role;
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000601';
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000601';
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610')$$,'42501',null,'accounting cannot send');
reset role;
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000601';
set local role authenticated;set local request.jwt.claims='{"aal":"aal1"}';
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610')$$,'42501',null,'admin requires MFA');
set local request.jwt.claims='{"aal":"aal2"}';
select lives_ok($$select public.order_confirmation_history((select id from report_orders where seq=1))$$,'admin with MFA may read');
reset role;
select ok((select relrowsecurity from pg_class where oid='app.order_confirmations'::regclass),'private ledger RLS enabled');
select ok(not has_table_privilege('authenticated','app.order_confirmations','select,insert,update,delete'),'no client table access');
select ok(not has_function_privilege('anon','public.prepare_order_confirmation(uuid,uuid,text)','execute'),'anonymous claim forbidden');
select ok(exists(select 1 from public.audit_log where action='confirmation_logged' and record_id=(select id from report_orders where seq=1)) and not exists(select 1 from public.audit_log where table_name='orders' and action like 'confirmation_%' and after::text like '%buyer@example.test%'),'completion and redacted audit committed together');
set local role authenticated;
select is(public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610','resend')->>'state','pending','local log does not prevent later explicit real delivery');
select throws_ok($$select public.prepare_order_confirmation((select id from report_orders where seq=1),'00000000-0000-4000-8000-000000000610','unknown')$$,'23514',null,'delivery mode validated');
select * from finish();rollback;
